public class CoinManager:MonoBehaviour
{
 [SerializeField] private TextMeshProUGUI textMeshPro;
public int totalCoins;
 public static CoinManager instance;
void Awake()
{
if (instance != null && instance != this) { Destroy(gameObject); return; }
instance = this;
}
private void Update()
{
_LoadCoins();
}
public void AddCoins(int amount)
{
totalCoins += amount;
}
public void SpendCoins(int amount)
{
totalCoins -= amount;
if (totalCoins < 0) totalCoins = 0;
}
private void _LoadCoins()
{
textMeshPro.text = totalCoins.ToString();
}
}

void Update()
{
    switch (currentState)
    {
        case BotBase.Startup:  Startup();  break;
        case BotBase.Idle:     idle();     break;
        case BotBase.Wondering: wondering(); break;
        case BotBase.Chase:    DoChase();  break;
        case BotBase.Attack:   attack();   break;
        case BotBase.Death:    death();    break;
        case BotBase.Off:
            Debug.LogWarning("Unknown state: " + currentState);
            break;
    }
}

