 public void ApplyStatusToPlayer(StatusEffect effect, int amount, int duration = 0)
{
   int finalAmount = amount;
  switch
 (effect){if (finalAmount > 0)
{
  playerWeakenStacks += finalAmount; 
  playerWeakenDuration = Mathf.Max(playerWeakenDuration, duration);
}
break;
   case StatusEffect.Vulnerable:
 if (finalAmount > 0)
{
  playerWeakenStacks += finalAmount;
 playerWeakenDuration = Mathf.Max(playerWeakenDuration, duration);
}
break;
 case StatusEffect.Poison: playerPoisonStacks += finalAmount; break;
  case StatusEffect.Bleed:
 if (finalAmount > 0)
{
 if (playerBleedStacks > 0)
{
 int dmg = CalculatePlayerStatusDamage(25);
  playerHealthBar.TakeDamage(dmg);
 playerBleedStacks = 0;
}
 else
{
  playerBleedStacks += finalAmount;
}
}
break;
 case StatusEffect.Frail:
 playerFrailStacks += finalAmount;
  playerFrailDuration = Mathf.Max(playerFrailDuration, duration);
  break;
 case StatusEffect.Stun:
 playerStunDuration = Mathf.Max(playerStunDuration, duration > 0 ? duration : finalAmount);
  break;
}}

